const __pageData = JSON.parse('{"title":"Docker快速入门","description":"从第 19 章\\"在 Linux 里装 MySQL\\"那一长串命令讲起，说清 Docker 是什么（快速构建、运行、管理应用的工具），再看同一条 docker run 怎么把 MySQL 装起来——镜像与容器、镜像仓库 Docker Hub、Client 到 daemon 的结构图、镜像命名规范 repository:tag，以及 -d/--name/-p/-e 四个参数与端口映射，最后把本机实测的 Docker 环境与\\"国内拉镜像\\"的坑记下来","frontmatter":{"title":"Docker快速入门","published":"2026-09-29T00:00:00.000Z","description":"从第 19 章\\"在 Linux 里装 MySQL\\"那一长串命令讲起，说清 Docker 是什么（快速构建、运行、管理应用的工具），再看同一条 docker run 怎么把 MySQL 装起来——镜像与容器、镜像仓库 Docker Hub、Client 到 daemon 的结构图、镜像命名规范 repository:tag，以及 -d/--name/-p/-e 四个参数与端口映射，最后把本机实测的 Docker 环境与\\"国内拉镜像\\"的坑记下来","tags":["JavaWeb","Docker","部署"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-110-docker-quickstart.webp","order":110,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/110-Docker快速入门.md","filePath":"posts/学习文档/JavaWeb学习笔记/110-Docker快速入门.md"}');
